const dbPath=process.env.DB_PATH||path.join(__dirname,'../data/codebattle.db');fs.mkdirSync(path.dirname(dbPath),{recursive:true});const db=new DatabaseSync(dbPath);db.exec('PRAGMA journal_mode=WAL');try{db.exec('ALTER TABLE Users ADD COLUMN is_admin INTEGER DEFAULT 0')}catch{}db.exec(`CREATE TABLE IF NOT EXISTS Users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT,created_at INTEGER NOT NULL,is_admin INTEGER DEFAULT 0);CREATE TABLE IF NOT EXISTS GuestSessions(id TEXT PRIMARY KEY,guest_id TEXT,last_active INTEGER,expires_at INTEGER);CREATE TABLE IF NOT EXISTS Matches(id TEXT PRIMARY KEY,player1 TEXT,player2 TEXT,language TEXT,difficulty TEXT,status TEXT,winner TEXT,ranked INTEGER,created_at INTEGER);CREATE TABLE IF NOT EXISTS Rounds(id TEXT PRIMARY KEY,match_id TEXT,round_number INTEGER,saboteur TEXT,debugger TEXT,challenge_id TEXT,result TEXT);CREATE TABLE IF NOT EXISTS Leaderboard(user_id TEXT,difficulty TEXT,points INTEGER DEFAULT 0,wins INTEGER DEFAULT 0,PRIMARY KEY(user_id,difficulty));CREATE TABLE IF NOT EXISTS Sessions(token TEXT PRIMARY KEY,user_id TEXT,expires_at INTEGER);CREATE TABLE IF NOT EXISTS Feedback(id TEXT PRIMARY KEY,user_id TEXT,username TEXT,type TEXT NOT NULL,subject TEXT NOT NULL,description TEXT NOT NULL,game_id TEXT,status TEXT DEFAULT 'open',created_at INTEGER NOT NULL);`);
