const proceduralByDifficulty = Object.fromEntries(['beginner','intermediate','advanced'].map(d=>[d,proceduralTemplates.filter(t=>t.difficulty===d)]));
function makeProceduralChallenge(t,language,difficulty){
 const cases=Array.from({length:9},()=>t.make());
 const seed=crypto.randomBytes(8).toString('hex');
 const c={id:`gen-${t.id}-${seed}`,title:t.title,category:t.category,difficulty,language,problem:t.statement,input:t.input,output:t.output,constraints:t.constraints,exampleInput:JSON.stringify(cases[0].input),exampleOutput:JSON.stringify(cases[0].output),referenceSolution:language==='python'?t.py:t.js,tests:cases.slice(0,3).map((x,i)=>({name:`case-${i+1}`,input:JSON.stringify(x.input),output:JSON.stringify(x.output)})),hidden:cases.slice(3).map((x,i)=>({name:`hidden-${i+1}`,input:JSON.stringify(x.input),output:JSON.stringify(x.output)}))};
 // Small wording variation prevents identical statements from feeling like a fixed quiz.
 const prefixes=['Solve this challenge: ','Your task: ','Challenge: ','Implement a function that will '];
 c.problem=prefixes[randInt(0,prefixes.length-1)]+t.statement.charAt(0).toLowerCase()+t.statement.slice(1);
 challengeStore.set(c.id,c); return c;
}

const challengeStore=new Map(challenges.map(c=>[c.id,c]));
const now=()=>Date.now();const sessions=new Map();const games=new Map();const queues=new Map();const rooms=new Map();
function uid(){return crypto.randomUUID()}function publicChallenge(c,lang){return {...c,referenceSolution:undefined,hidden:undefined,referenceSolution:undefined,language:lang,referenceSolution:undefined,tests:c.tests}}
function getUser(req){const token=req.cookies?.cb_session;if(!token)return null;const s=db.prepare('SELECT * FROM Sessions WHERE token=?').get(token);if(!s||s.expires_at<now()){return null}const u=db.prepare('SELECT id,username,is_admin FROM Users WHERE id=?').get(s.user_id);if(u)return {...u,is_admin:!!u.is_admin};const g=db.prepare('SELECT id,guest_id FROM GuestSessions WHERE id=?').get(s.user_id);return g?{id:g.id,username:g.guest_id,guest:true}:null}
function auth(req,res,next){const u=getUser(req);if(!u)return res.status(401).json({error:'Authentication required'});req.user=u;next()}
function createSession(res,userId){const token=crypto.randomBytes(32).toString('hex');db.prepare('INSERT INTO Sessions VALUES(?,?,?)').run(token,userId,now()+1000*60*60*24*30);res.cookie('cb_session',token,{httpOnly:true,sameSite:'lax',secure:false,maxAge:1000*60*60*24*30});}
(async()=>{try{const admin=db.prepare('SELECT id FROM Users WHERE username=?').get('admin');if(!admin){const id=uid();const hash=await bcrypt.hash(process.env.ADMIN_PASSWORD||'CodeBattleAdmin123!',12);db.prepare('INSERT INTO Users(id,username,password_hash,created_at,is_admin) VALUES(?,?,?,?,0)').run(id,'admin',hash,now());for(const d of ['beginner','intermediate','advanced'])db.prepare('INSERT INTO Leaderboard VALUES(?,?,0,0)').run(id,d)}}catch(e){console.error('Admin bootstrap failed:',e.message)}})();
app.post('/api/register',async(req,res)=>{try{const {username,password}=req.body;if(username==='admin')return res.status(409).json({error:'The admin username is reserved.'});if(!/^[a-zA-Z0-9_]{3,24}$/.test(username))return res.status(400).json({error:'Username must be 3–24 letters, numbers or underscores.'});if(!password||password.length<8)return res.status(400).json({error:'Password must be at least 8 characters.'});const id=uid();const hash=await bcrypt.hash(password,12);db.prepare('INSERT INTO Users(id,username,password_hash,created_at,is_admin) VALUES(?,?,?,?,?)').run(id,username,hash,now(),username==='admin'?1:0);for(const d of ['beginner','intermediate','advanced'])db.prepare('INSERT INTO Leaderboard VALUES(?,?,0,0)').run(id,d);createSession(res,id);res.json({user:{id,username,is_admin:username==='admin'}})}catch(e){res.status(409).json({error:'Username already exists.'})}});
app.post('/api/login',async(req,res)=>{const u=db.prepare('SELECT * FROM Users WHERE username=?').get(req.body.username);if(!u||!(await bcrypt.compare(req.body.password||'',u.password_hash)))return res.status(401).json({error:'Invalid username or password.'});createSession(res,u.id);res.json({user:{id:u.id,username:u.username,is_admin:!!u.is_admin}})});
app.post('/api/guest',(req,res)=>{const id=uid(),guest='Guest-'+crypto.randomBytes(3).toString('hex').toUpperCase();db.prepare('INSERT INTO GuestSessions VALUES(?,?,?,?)').run(id,guest,now(),now()+1000*60*60*24*7);createSession(res,id);res.json({user:{id,username:guest,guest:true}})});
app.post('/api/logout',(req,res)=>{const t=req.cookies?.cb_session;if(t)db.prepare('DELETE FROM Sessions WHERE token=?').run(t);res.clearCookie('cb_session');res.json({ok:true})});app.get('/api/me',(req,res)=>res.json({user:getUser(req)}));

function requireAdmin(req,res,next){
 const u=req.user;
 if(!u||u.guest||(!u.is_admin && u.username!=='admin')) return res.status(403).json({error:'Admin access required.'});
 req.admin=u; next();
}
app.post('/api/feedback',auth,(req,res)=>{
 const u=req.user;if(!u||u.guest)return res.status(401).json({error:'Please register or log in to submit feedback.'});
 const type=String(req.body.type||'Other').trim();const subject=String(req.body.subject||'').trim();const description=String(req.body.description||'').trim();const gameId=req.body.game_id?String(req.body.game_id).trim():null;
 if(!['Bug Report','Feature Request','Game Issue','Other'].includes(type))return res.status(400).json({error:'Invalid feedback type.'});
 if(!subject||subject.length>120)return res.status(400).json({error:'Subject is required and must be 120 characters or fewer.'});
 if(!description||description.length>4000)return res.status(400).json({error:'Description is required and must be 4000 characters or fewer.'});
 const id=uid();db.prepare('INSERT INTO Feedback(id,user_id,username,type,subject,description,game_id,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)').run(id,u.id,u.username,type,subject,description,gameId,'open',now());res.json({ok:true,id});
});
