app.post('/api/admin/feedback/:id/status',auth,requireAdmin,(req,res)=>{const status=String(req.body.status||'');if(!['open','in_progress','resolved'].includes(status))return res.status(400).json({error:'Invalid feedback status.'});const r=db.prepare('UPDATE Feedback SET status=? WHERE id=?').run(status,req.params.id);if(!r.changes)return res.status(404).json({error:'Feedback not found.'});res.json({ok:true});});
