function safeJson(s){try{return JSON.stringify(JSON.parse(s))}catch{return JSON.stringify(s)}}
function execute(language,code,input,timeout=2500){return new Promise(resolve=>{const dir=fs.mkdtempSync(path.join(require('os').tmpdir(),'cb-'));let file,cmd,args;const runner=`const fs=require('fs');const input=fs.readFileSync(0,'utf8');let data;try{data=JSON.parse(input)}catch{data=input};\n${code}\nPromise.resolve(solve(data)).then(v=>process.stdout.write(JSON.stringify(v))).catch(e=>{console.error(e.message);process.exit(2)});`;if(language==='javascript'){file=path.join(dir,'main.js');fs.writeFileSync(file,runner);cmd=process.execPath;args=[file]}else{file=path.join(dir,'main.py');const py=`import sys,json\n${code}\nraw=sys.stdin.read()\ntry: data=json.loads(raw)\nexcept: data=raw\ntry: print(json.dumps(solve(data),separators=(',',':')))\nexcept Exception as e:\n print(str(e),file=sys.stderr);sys.exit(2)`;fs.writeFileSync(file,py);cmd=process.platform==='win32'?'python':'python3';args=[file]}let out='',err='';const p=spawn(cmd,args,{cwd:dir,stdio:['pipe','pipe','pipe']});p.stdout.on('data',d=>out+=d);p.stderr.on('data',d=>err+=d);const kill=setTimeout(()=>{p.kill('SIGKILL');resolve({ok:false,error:'Execution timed out'});fs.rmSync(dir,{recursive:true,force:true})},timeout);p.on('close',()=>{clearTimeout(kill);const result={ok:p.exitCode===0,output:out.trim(),error:err.trim()};fs.rmSync(dir,{recursive:true,force:true});resolve(result) });p.stdin.end(input);})}
async function runTests(c,language,code,hidden){const all=(hidden?c.hidden:c.tests)||[];const results=[];for(const t of all){const r=await execute(language,code,t.input);const expected=safeJson(t.output);const pass=r.ok&&r.output===expected;results.push({name:t.name,pass,message:pass?'Passed':r.error||`Expected ${expected}, got ${r.output||'<no output>'}`});if(!pass&&hidden){} }return results}
app.post('/api/execute',async(req,res)=>{const {challengeId,language,code,publicOnly=false}=req.body;const c=challengeStore.get(challengeId)||challenges.find(x=>x.id===challengeId);if(!c)return res.status(404).json({error:'Challenge not found'});const results=await runTests(c,language,code,!publicOnly);res.json({tests:results,passed:results.every(x=>x.pass)});});
function diffChangedLines(a,b){const A=a.split('\n'),B=b.split('\n');let i=0,j=0,changed=new Set();while(i<A.length&&j<B.length){if(A[i]===B[j]){i++;j++;continue}changed.add(i+1);i++;j++;}while(i<A.length){changed.add(i+1);i++}while(j<B.length){changed.add(Math.max(1,i));j++}return changed.size}
function randInt(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function pickChallenge(language,difficulty,used=[]){const procedural=proceduralByDifficulty[difficulty]||[];const useProcedural=procedural.length>0;if(useProcedural){return makeProceduralChallenge(procedural[randInt(0,procedural.length-1)],language,difficulty)}const pool=challenges.filter(c=>c.difficulty===difficulty);const fresh=pool.filter(c=>!used.includes(c.id));const base=(fresh.length?fresh:pool)[randInt(0,(fresh.length?fresh:pool).length-1)];return generateVariant(base,language,difficulty)}
function generateVariant(base,language,difficulty){const c=language==='python'?{...base,language:'python',referenceSolution:pyEquivalent[base.id]}:{...base};c.id=`${base.id}-v${crypto.randomBytes(4).toString('hex')}`;
if(base.id==='js-beg-arr'){const make=()=>Array.from({length:randInt(0,difficulty==='advanced'?14:9)},()=>randInt(-50,50));const arrays=Array.from({length:7},make);const sum=a=>a.reduce((x,y)=>x+y,0);c.title=['Repair the Total','Restore the Array Sum','Array Sum Audit'][randInt(0,2)];c.problem=['Return the sum of every integer in the supplied array. Empty arrays must return 0.','Calculate the total of all values in an integer array, including negative values.','Audit an integer array and produce its arithmetic total; an empty array has total 0.'][randInt(0,2)];c.exampleInput=JSON.stringify(arrays[0]);c.exampleOutput=String(sum(arrays[0]));const ts=arrays.map((a,i)=>({name:`case-${i+1}`,input:JSON.stringify(a),output:String(sum(a))}));c.tests=ts.slice(0,3);c.hidden=ts.slice(3)}
else if(base.id==='js-beg-str'){const words=['debug','education','rhythm','algorithm','review','compiler','array','python','javascript','competition','learning'];const w=words[randInt(0,words.length-1)];const idx=[...w].findIndex(ch=>'aeiou'.includes(ch));c.title=['First Vowel','Vowel Detector','Locate the First Vowel'][randInt(0,2)];c.problem=['Return the zero-based position of the first lowercase vowel in the string, or -1 if none exists.','Scan the supplied lowercase text and report where its first vowel occurs. Return -1 when no vowel is present.','Find the earliest a/e/i/o/u in the string and return its index.'][randInt(0,2)];c.exampleInput=JSON.stringify(w);c.exampleOutput=String(idx);const ts=words.map((x,i)=>({name:`case-${i+1}`,input:JSON.stringify(x),output:String([...x].findIndex(ch=>'aeiou'.includes(ch)))}));c.tests=ts.slice(0,3);c.hidden=ts.slice(3)}
else if(base.id==='js-int-loop'){const ts=[];for(let i=0;i<7;i++){const a=Array.from({length:randInt(1,12)},()=>randInt(-40,40));ts.push({name:`case-${i+1}`,input:JSON.stringify(a),output:String(a.filter(x=>x%2===0).length)})}c.problem=['Count the even integers in the array. Zero and negative values are valid inputs.','Determine how many values are divisible by two.','Return the number of even elements in the supplied integer array.'][randInt(0,2)];c.exampleInput=ts[0].input;c.exampleOutput=ts[0].output;c.tests=ts.slice(0,3);c.hidden=ts.slice(3)}
else if(base.id==='js-int-search'){const ts=[];for(let i=0;i<7;i++){const a=Array.from({length:randInt(0,10)},()=>randInt(-30,30)).sort((x,y)=>x-y);const target=a.length&&Math.random()<.65?a[randInt(0,a.length-1)]:randInt(-30,30);let lo=0,hi=a.length-1,ans=-1;while(lo<=hi){const m=Math.floor((lo+hi)/2);if(a[m]===target){ans=m;break}if(a[m]<target)lo=m+1;else hi=m-1}ts.push({name:`case-${i+1}`,input:JSON.stringify({arr:a,target}),output:String(ans)})}c.problem=['Find the index of target in the sorted array using binary search; return -1 if absent.','Search the ordered array efficiently and return the target position, or -1 when it is not present.','Locate a target in ascending order data using binary search.'][randInt(0,2)];c.exampleInput=ts[0].input;c.exampleOutput=ts[0].output;c.tests=ts.slice(0,3);c.hidden=ts.slice(3)}
else if(base.id==='js-adv-math'){const ts=[];for(let i=0;i<7;i++){const a=Array.from({length:randInt(0,14)},()=>randInt(-30,40));let best=a.length?1:0,run=best;for(let j=1;j<a.length;j++){run=a[j]>a[j-1]?run+1:1;best=Math.max(best,run)}ts.push({name:`case-${i+1}`,input:JSON.stringify(a),output:String(best)})}c.problem=['Return the length of the longest contiguous strictly increasing run. Equal adjacent values break a run.','Measure the longest adjacent chain where every next number is greater than the previous one.','Find the maximum length of a strictly rising contiguous segment.'][randInt(0,2)];c.exampleInput=ts[0].input;c.exampleOutput=ts[0].output;c.tests=ts.slice(0,3);c.hidden=ts.slice(3)}
challengeStore.set(c.id,c);return c}
function phaseGame(g){g.phase='sabotage';g.phaseLabel='SABOTAGE';g.phaseEndsAt=now()+g.sabotageSeconds*1000;g.challenge=publicChallenge(g.challenge,g.language);broadcast(g)}
function broadcast(g){for(const p of g.players){if(p.socketId)io.to(p.socketId).emit('game:state',sanitizeGame(g,p.id))}}
function sanitizeGame(g,viewerId){const role=g.roles?.[viewerId];const canSeeCode=role==='saboteur'||g.phase!=='sabotage';return {matchId:g.id,ranked:!!g.ranked,players:g.players.map(p=>({id:p.id,username:p.username})),opponentId:g.players.find(p=>p.id!==viewerId)?.id,roles:g.roles,scores:g.scores,roundNumber:g.roundNumber,phase:g.phase,phaseLabel:g.phaseLabel,phaseEndsAt:g.phaseEndsAt,challenge:{id:g.challenge.id,title:g.challenge.title,problem:g.challenge.problem,input:g.challenge.input,output:g.challenge.output,constraints:g.challenge.constraints,exampleInput:g.challenge.exampleInput,exampleOutput:g.challenge.exampleOutput},code:canSeeCode?g.currentCode:'',maxChanges:g.maxChanges,language:g.language,difficulty:g.difficulty,winnerId:g.winnerId,resultMessage:g.resultMessage};}
function randomChangeLimit(difficulty){return Math.random()<0.5?1:2}

function beginGame(id){const g=games.get(id);g.usedChallenges=[];g.challenge=g.custom||pickChallenge(g.language,g.difficulty,g.usedChallenges);if(!g.custom)g.usedChallenges.push(g.challenge.id.split('-v')[0]);g.roles=g.botId?{[g.players[0].id]:'debugger',[g.botId]:'saboteur'}:{[g.players[0].id]:'saboteur',[g.players[1].id]:'debugger'};g.scores={[g.players[0].id]:g.scores[g.players[0].id]||0,[g.players[1].id]:g.scores[g.players[1].id]||0};g.roundNumber=g.roundNumber||1;g.currentCode=g.challenge.referenceSolution;g.originalCode=g.challenge.referenceSolution;g.sabotageSeconds=g.sabotageSeconds||45;g.debugSeconds=g.debugSeconds||180;g.maxChanges=randomChangeLimit(g.difficulty);g.phase='sabotage';g.phaseLabel='SABOTAGE';g.phaseEndsAt=now()+g.sabotageSeconds*1000;db.prepare('INSERT INTO Rounds VALUES(?,?,?,?,?,?,?)').run(uid(),g.id,g.roundNumber,Object.entries(g.roles).find(([,r])=>r==='saboteur')[0],Object.entries(g.roles).find(([,r])=>r==='debugger')[0],g.challenge.id,null);for(const p of g.players){if(p.socketId)io.to(p.socketId).emit('match:found',sanitizeGame(g,p.id));}broadcast(g)}
function createGame(players,opts,ranked=false,extra={}){const id=uid();const g={id,players,botId:extra.botId||null,botSkill:extra.botSkill||opts.difficulty,language:opts.language,difficulty:opts.difficulty,custom:opts.custom||null,ranked,roundNumber:1,scores:{},sabotageSeconds:opts.sabotageSeconds||45,debugSeconds:opts.debugSeconds||180,maxChanges:opts.maxChanges||3};games.set(id,g);for(const p of players)io.sockets.sockets.get(p.socketId)?.join(id);beginGame(id);return g}
function nextRound(g){if(g.scores[g.players[0].id]>=3||g.scores[g.players[1].id]>=3){finishMatch(g);return}g.roundNumber++;const ids=g.players.map(p=>p.id);g.roles={[ids[0]]:g.roles[ids[1]]==='saboteur'?'saboteur':'debugger',[ids[1]]:g.roles[ids[0]]==='saboteur'?'saboteur':'debugger'};g.challenge=pickChallenge(g.language,g.difficulty,g.usedChallenges||[]);g.usedChallenges=g.usedChallenges||[];g.usedChallenges.push(g.challenge.id.split('-v')[0]);g.originalCode=g.challenge.referenceSolution;g.currentCode=g.originalCode;g.phase='sabotage';g.phaseLabel='SABOTAGE';g.phaseEndsAt=now()+g.sabotageSeconds*1000;db.prepare('INSERT INTO Rounds VALUES(?,?,?,?,?,?,?)').run(uid(),g.id,g.roundNumber,Object.entries(g.roles).find(([,r])=>r==='saboteur')[0],Object.entries(g.roles).find(([,r])=>r==='debugger')[0],g.challenge.id,null);broadcast(g);if(g.botId&&g.roles[g.botId]==='saboteur')setTimeout(()=>botSabotage(g),900)}
function finishMatch(g){g.phase='ended';g.phaseLabel='MATCH COMPLETE';if(!g.winnerId)g.winnerId=g.scores[g.players[0].id]>g.scores[g.players[1].id]?g.players[0].id:g.players[1].id;g.resultMessage=g.resultMessage||'Match complete';db.prepare('UPDATE Matches SET status=?,winner=? WHERE id=?').run('complete',g.winnerId,g.id);if(g.ranked){const winner=g.winnerId;const wu=g.players.find(p=>p.id===winner);if(wu&&!wu.guest){db.prepare('INSERT INTO Leaderboard(user_id,difficulty,points,wins) VALUES(?,?,1,1) ON CONFLICT(user_id,difficulty) DO UPDATE SET points=points+1,wins=wins+1').run(winner,g.difficulty)}}broadcast(g);io.to(g.id).emit('match:ended',sanitizeGame(g))}
setInterval(async()=>{for(const g of games.values()){if(g.phase==='ended')continue;if(now()>=g.phaseEndsAt){if(g.phase==='sabotage'){g.currentCode=g.currentCode||g.originalCode;g.phase='debug';g.phaseLabel='DEBUG';g.phaseEndsAt=now()+g.debugSeconds*1000;broadcast(g);if(g.botId&&g.roles[g.botId]==='debugger')botDebug(g)}else if(g.phase==='debug'){g.resultMessage='Debugger ran out of time.';const sab=Object.entries(g.roles).find(([,r])=>r==='saboteur')[0];g.scores[sab]=(g.scores[sab]||0)+1;g.result='saboteur';db.prepare('UPDATE Rounds SET result=? WHERE match_id=? AND round_number=?').run('saboteur',g.id,g.roundNumber);broadcast(g);setTimeout(()=>nextRound(g),1500)}}}},250);
io.use((socket,next)=>{const cookie=socket.handshake.headers.cookie||'';const m=cookie.match(/cb_session=([^;]+)/);if(!m)return next(new Error('Not authenticated'));const s=db.prepare('SELECT * FROM Sessions WHERE token=?').get(m[1]);if(!s||s.expires_at<now())return next(new Error('Session expired'));let u=db.prepare('SELECT id,username,is_admin FROM Users WHERE id=?').get(s.user_id);if(!u){const g=db.prepare('SELECT id,guest_id FROM GuestSessions WHERE id=?').get(s.user_id);if(g)u={id:g.id,username:g.guest_id,guest:true}}if(!u)return next(new Error('User missing'));socket.user=u;next()});
async function botSabotage(g){if(g.phase!=='sabotage'||g.roles[g.botId]!=='saboteur')return;const lines=g.originalCode.split('\n');const candidates=[];for(let i=0;i<lines.length;i++){const l=lines[i];if(/===|>|<|\+\+|--|return|\+=|-=|%/.test(l))candidates.push(i)}let count=Math.min(g.maxChanges,1+(Math.random()<.35?1:0));let used=new Set();for(let k=0;k<count;k++){let i=candidates.filter(x=>!used.has(x))[randInt(0,Math.max(0,candidates.filter(x=>!used.has(x)).length-1))];if(i==null)break;used.add(i);lines[i]=sabotageLine(lines[i],g.language,g.botSkill)}g.currentCode=lines.join('\n');setTimeout(()=>lockSabotage(g,g.currentCode),1200+randInt(300,1800))}
function sabotageLine(line,language,skill){if(language==='javascript'){if(line.includes('==='))return line.replace('===','!==');if(line.includes('>'))return line.replace('>','>=');if(line.includes('<'))return line.replace('<','<=');if(line.includes('++'))return line.replace('++','--');if(line.includes('+='))return line.replace('+=','-=');if(line.includes('return'))return line.replace(/return\s+([^;]+)/,'return 0');}else{if(line.includes('=='))return line.replace('==','!=');if(line.includes('>'))return line.replace('>','>=');if(line.includes('<'))return line.replace('<','<=');if(line.includes('+='))return line.replace('+=','-=');if(line.includes('return'))return line.replace(/return\s+(.+)/,'return 0')}return line}
function lockSabotage(g,source){if(g.phase!=='sabotage')return;g.currentCode=source;g.changedLines=diffChangedLines(g.originalCode,source);if(g.changedLines>g.maxChanges){g.currentCode=g.originalCode;return}g.phase='debug';g.phaseLabel='DEBUG';g.phaseEndsAt=now()+g.debugSeconds*1000;broadcast(g);if(g.botId&&g.roles[g.botId]==='debugger')botDebug(g)}
async function botDebug(g){if(g.phase!=='debug'||g.roles[g.botId]!=='debugger')return;const willWin=Math.random()>(g.botLoseChance||0.2);const delay=Math.min(g.debugSeconds*1000-500,willWin?(g.botSkill==='advanced'?randInt(5000,18000):g.botSkill==='intermediate'?randInt(7000,25000):randInt(9000,30000)):randInt(8000,Math.max(9000,g.debugSeconds*1000-1000)));setTimeout(async()=>{if(g.phase!=='debug')return;if(!willWin){g.resultMessage='CodeBot made an intentional mistake and lost the round.';const human=g.players.find(p=>p.id!==g.botId)?.id;g.scores[human]=(g.scores[human]||0)+1;g.phase='ended';g.phaseLabel='ROUND COMPLETE';broadcast(g);setTimeout(()=>nextRound(g),1400);return}const broken=g.currentCode.split('\n'),correct=g.originalCode.split('\n'),sab=g.players.find(p=>p.id!==g.botId);let step=0;const timer=setInterval(()=>{if(g.phase!=='debug'){clearInterval(timer);return}if(step>=correct.length){clearInterval(timer);g.currentCode=g.originalCode;g.scores[g.botId]=(g.scores[g.botId]||0)+1;g.resultMessage='CodeBot fixed the program.';g.phase='ended';g.phaseLabel='ROUND COMPLETE';broadcast(g);setTimeout(()=>nextRound(g),1400);return}const lineDiff=broken[step]!==correct[step];if(lineDiff){g.currentCode=correct.slice(0,step+1).concat(broken.slice(step+1)).join('\n');if(sab)io.to(sab.socketId).emit('game:liveCode',{source:g.currentCode})}step++},Math.max(180,Math.floor(delay/Math.max(1,correct.length))))},delay)}
io.on('connection',socket=>{
 socket.on('computer:start',opts=>{const human={id:socket.user.id,username:socket.user.username,socketId:socket.id};const botId='bot-'+uid();const bot={id:botId,username:'CodeBot',socketId:null,guest:true};const g=createGame([human,bot],opts,false,{botId,botSkill:opts.difficulty});g.botLoseChance=opts.difficulty==='beginner'?0.42:opts.difficulty==='intermediate'?0.28:0.18;broadcast(g);setTimeout(()=>botSabotage(g),900);});
 socket.on('queue:join',opts=>{if(opts.ranked&&socket.user.guest)return socket.emit('error:game',{message:'Ranked matches require a registered account so your points can be persisted.'});const key=`${opts.language}:${opts.difficulty}`;if(!queues.has(key))queues.set(key,[]);const q=queues.get(key);q.push({id:socket.user.id,username:socket.user.username,socketId:socket.id});socket.emit('matchmaking:waiting',opts);if(q.length>=2){const a=q.shift(),b=q.shift();db.prepare('INSERT INTO Matches VALUES(?,?,?,?,?,?,?,?,?)').run(uid(),a.id,b.id,opts.language,opts.difficulty,'active',null,opts.ranked?1:0,now());createGame([a,b],opts,!!opts.ranked)}});
 socket.on('queue:leave',()=>{for(const q of queues.values()){const i=q.findIndex(x=>x.id===socket.user.id);if(i>=0)q.splice(i,1)}});
 socket.on('room:create',async opts=>{let custom=null;if(opts.custom?.enabled){try{const tests=JSON.parse(opts.custom.tests||'[]');if(!opts.custom.title||!opts.custom.problem||!opts.custom.solution||!Array.isArray(tests)||!tests.length)throw Error('Custom challenge needs title, statement, solution and at least one test.');const cid='custom-'+uid();custom={id:cid,title:opts.custom.title,difficulty:opts.difficulty,category:'Custom',language:opts.language,problem:opts.custom.problem,input:opts.custom.input||'',output:opts.custom.output||'',constraints:opts.custom.constraints||'',exampleInput:tests[0].input,exampleOutput:tests[0].output,referenceSolution:opts.custom.solution,tests,hidden:tests};challengeStore.set(cid,custom);const vr=await runTests(custom,opts.language,opts.custom.solution,true);if(!vr.every(x=>x.pass))return socket.emit('error:game',{message:'Custom solution failed validation. Fix the solution/tests before creating the room.'});}catch(e){return socket.emit('error:game',{message:e.message||'Invalid custom challenge.'})}}const code='CB'+crypto.randomBytes(2).toString('hex').toUpperCase();rooms.set(code,{code,host:socket.user.id,language:opts.language,difficulty:opts.difficulty,custom,players:[{id:socket.user.id,username:socket.user.username,socketId:socket.id}]});socket.join('room:'+code);socket.emit('room:created',rooms.get(code))});
 socket.on('room:join',({code})=>{const r=rooms.get(code);if(!r)return socket.emit('error:game',{message:'Room not found or expired.'});if(r.players.length>=2)return socket.emit('error:game',{message:'Room is full.'});r.players.push({id:socket.user.id,username:socket.user.username,socketId:socket.id});socket.join('room:'+code);io.to('room:'+code).emit('room:state',r);socket.emit('room:joined',r)});
 socket.on('room:start',({code})=>{const r=rooms.get(code);if(!r||r.host!==socket.user.id||r.players.length!==2)return;const opts={language:r.language,difficulty:r.difficulty,custom:r.custom};const g=createGame(r.players,opts,false);r.gameId=g.id});
 socket.on('round:sabotage:update',({code,source})=>{const g=games.get(code);if(!g||g.phase!=='sabotage'||g.roles[socket.user.id]!=='saboteur')return;const n=diffChangedLines(g.originalCode,source);if(n<=g.maxChanges){g.currentCode=source;socket.emit('game:sabotageCount',{count:n,max:g.maxChanges})}});
 socket.on('round:lock',({code,source})=>{const g=games.get(code);if(!g||g.phase!=='sabotage')return;if(g.roles[socket.user.id]!=='saboteur')return socket.emit('error:game',{message:'Only the Saboteur can lock sabotage.'});const n=diffChangedLines(g.originalCode,source);if(n<1)return socket.emit('error:game',{message:'Make at least one change before locking.'});if(n>g.maxChanges)return socket.emit('error:game',{message:`Maximum ${g.maxChanges} changed lines allowed. Server counted ${n}.`});lockSabotage(g,source);});
 socket.on('round:debug:update',({code,source})=>{const g=games.get(code);if(!g||g.phase!=='debug'||g.roles[socket.user.id]!=='debugger')return;g.currentCode=source;const sab=g.players.find(p=>p.id!==socket.user.id);if(sab)io.to(sab.socketId).emit('game:liveCode',{source})});
 socket.on('round:submit',async({code,source})=>{const g=games.get(code);if(!g||g.phase!=='debug')return;if(g.roles[socket.user.id]!=='debugger')return;const c=g.challenge;const results=await runTests(c,g.language,source,true);io.to(g.id).emit('game:testResult',{tests:results});if(results.every(x=>x.pass)){g.scores[socket.user.id]=(g.scores[socket.user.id]||0)+1;g.resultMessage='Debugger fixed the program!';g.winnerId=null;g.phase='ended';g.phaseLabel='ROUND COMPLETE';db.prepare('UPDATE Rounds SET result=? WHERE match_id=? AND round_number=?').run('debugger',g.id,g.roundNumber);broadcast(g);setTimeout(()=>nextRound(g),1800)}});
 socket.on('fairplay:exit',({code})=>{const g=games.get(code);if(!g||!g.ranked||g.phase==='ended')return;g.fsViolations=g.fsViolations||{};g.fsViolations[socket.user.id]=(g.fsViolations[socket.user.id]||0)+1;const n=g.fsViolations[socket.user.id];io.to(socket.id).emit('fairplay:count',{count:n});if(n>=3){const winner=g.players.find(p=>p.id!==socket.user.id)?.id;if(winner){g.winnerId=winner;g.scores[winner]=Math.max(g.scores[winner]||0,3);g.resultMessage='Match forfeited: fullscreen exited three times.';finishMatch(g)}}});
 socket.on('fairplay:timeout',({code})=>{const g=games.get(code);if(!g||!g.ranked||g.phase==='ended')return;const winner=g.players.find(p=>p.id!==socket.user.id)?.id;if(winner){g.winnerId=winner;g.scores[winner]=Math.max(g.scores[winner]||0,3);g.resultMessage='Match forfeited: fullscreen was exited for more than 10 seconds.';finishMatch(g)}});
 socket.on('disconnect',()=>{for(const q of queues.values()){const i=q.findIndex(x=>x.socketId===socket.id);if(i>=0)q.splice(i,1)}for(const g of games.values()){const p=g.players.find(x=>x.socketId===socket.id);if(p&&g.phase!=='ended'){io.to(g.id).emit('opponent:disconnected',{message:`${p.username} disconnected. Match ended.`});g.phase='ended';g.phaseLabel='MATCH ENDED';broadcast(g)}}});
});
